     function Question({ id, prompt, helpText, options }) {
       const helpId = helpText ? id + "-help" : "";

       return `
         <div class="form-field">
           <fieldset ${helpId ? `aria-describedby="${helpId}"` : ""}>
             <legend>${prompt}</legend>
             ${helpText ? `<p class="help-text" id="${helpId}">${helpText}</p>` : ""}
